using System;
using Astrea.BattleActions;
using Astrea.GameElements;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "DiceTargetCastStateMouseAction", menuName = "Data/Battle/Actions/DiceTargetCastStateMouseAction")]
public class DiceTargetCastStateMouseAction : Action
{
	[Header("References")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	[SerializeField]
	private DiceTargetCastSpaceInstancesReference diceTargetCastSpaceInstancesReference;

	[SerializeField]
	private VoidEvent OnShowChooseDiceSlotCanvas;

	private bool diceSelected;

	private DiceActionLogic_ChooseDice diceActionLogic_ChooseDice => actionInstanceReference.Value.ActionFace.BattleAction.GetDiceActionLogic(actionInstanceReference.Value.ActionFace.ModifiedActionValue) as DiceActionLogic_ChooseDice;

	private System.Action noValidRaycastMouseInputAction => delegate
	{
		if (base.actionInstance != null)
		{
			base.actionInstance.StopFollowingMouse();
			Debug.Log("NOT A DICE CAST TARGET SPACE");
		}
		else
		{
			Debug.Log("No UI Object");
		}
	};

	public override void OnStartState()
	{
		ActionInstance currentActionInstance = ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance;
		actionInstanceReference.SetValue(currentActionInstance);
		diceActionLogic_ChooseDice.OnChooseDiceStateEvent.Raise();
		diceSelected = false;
	}

	public override void Execute(float d)
	{
		base.inputManager.MouseInput(delegate(GameObject gameObject)
		{
			if (!diceSelected)
			{
				DiceInstance chosenDice = gameObject.GetComponentInParent<DiceInstance>();
				if (chosenDice != null)
				{
					if (chosenDice.CheckPointAndClickDraggableStates(diceActionLogic_ChooseDice.ChooseDicesState, playCantUseActionFeedback: true) && chosenDice.ChooseDiceStateCheckCondition() && chosenDice.DiceState != DiceState.Dragged)
					{
						OnShowChooseDiceSlotCanvas.Raise();
						diceSelected = true;
						ActionFace actionFace = base.actionInstance.ActionFace;
						DiceTargetCastSpaceInstance diceTargetCastSpaceInstanceDropped = diceTargetCastSpaceInstancesReference.diceTargetCastSpaceInstances.First();
						ReferenceSingleton<InputManager>.Instance.MoveActionInstanceToDicePlacementCastAction(delegate
						{
							(actionFace.BattleAction as ChooseDiceAction).ActionSelected(actionFace.ModifiedActionValue);
							diceTargetCastSpaceInstanceDropped.ActionDrop(chosenDice, setDiceInstancePosition: false);
						});
						ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
						chosenDice.ChooseDiceStateFirstDiceChosen(diceTargetCastSpaceInstanceDropped.transform.position);
						actionInstanceReference.Value.ActionDroppedOnBattleActionCastSpace();
					}
				}
				else
				{
					DicePlacement componentInChildren = gameObject.GetComponentInChildren<DicePlacement>();
					if (componentInChildren != null)
					{
						ActionFace actionFace2 = base.actionInstance.ActionFace;
						actionInstanceReference.SetValue(base.actionInstance);
						(actionFace2.BattleAction as ChooseDiceAction).ActionSelected(actionFace2.ModifiedActionValue);
						base.actionInstance.ActionDroppedOnBattleActionCastSpace();
						Vector3 diceOnTargetCastSpacePositionAdjustment = ReferenceSingleton<InputManager>.Instance.GetDiceOnTargetCastSpacePositionAdjustment(componentInChildren.transform.position, base.actionInstance is DiceInstance);
						base.actionInstance.transform.position = diceOnTargetCastSpacePositionAdjustment;
						ReferenceSingleton<BattleHandler>.Instance.SetCurrentActionInstance(null);
						OnShowChooseDiceSlotCanvas.Raise();
					}
					else
					{
						base.actionInstance.StopFollowingMouse();
						Debug.Log("TARGETSELECTING: Not a target");
					}
				}
			}
		}, noValidRaycastMouseInputAction, base.actionInstance != null);
	}
}
